<script>
  import { onMount } from 'svelte';
  import { Plus, CalendarClock, Play, Pause, Activity, Check, X, RefreshCw, ShieldCheck, Trash2, Undo2 } from 'lucide-svelte';
  import { api,query } from '../api.js';
  import Modal from '../Modal.svelte';
  let { workspaceId=null,models=[],defaultModel='',allowed=false,canWrite=true,user }=$props();
  let jobs=$state([]),templates=$state([]),connections=$state([]),creating=$state(false),editingJob=$state(null),busy=$state(false),error=$state(''),notice=$state(''),selected=$state(''),runs=$state([]),now=$state(Date.now());
  let name=$state(''),instructions=$state(''),taskType=$state('analysis'),model=$state(''),firstRun=$state(''),interval=$state(15),timezone=$state(Intl.DateTimeFormat().resolvedOptions().timeZone),consent=$state(false),dependencyIds=$state([]),policy=$state('pass_warn'),metrics=$state([]),windowMinutes=$state(15),rejecting=$state(null),comment=$state(''),draftQuestions=$state([]),draftConfig=$state({});
  let clock;
  const options=$derived(models.map(m=>typeof m==='string'?m:m.id));
  const fmt=v=>v?new Date(v).toLocaleString():'—';
  const local=v=>{const d=v?new Date(v):new Date(Date.now()+60000);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
  onMount(()=>{load();clock=setInterval(()=>now=Date.now(),1000);return()=>clearInterval(clock);});
  async function load(){try{const [all,t,c]=await Promise.all([api('/jobs'),api('/jobs/templates'),api('/connections'+query({workspace_id:workspaceId}))]);jobs=all.filter(j=>workspaceId?j.workspace_id===workspaceId:!j.workspace_id);templates=t;connections=c.filter(c=>c.provider==='influxdb'&&c.status!=='disconnected');}catch(e){error=e.message;}}
  function create(){editingJob=null;draftQuestions=[];draftConfig={};name='';instructions='';taskType='analysis';model=options.includes(defaultModel)?defaultModel:options[0]||'';firstRun=local();interval=15;dependencyIds=[];metrics=[];consent=false;windowMinutes=15;error='';creating=true;}
  function edit(job){editingJob=job;draftConfig=job.config||{};draftQuestions=[];name=job.name;instructions=job.instructions;taskType=job.task_type;model=job.model;firstRun=local(job.next_run_at);interval=job.interval_minutes;timezone=job.timezone;consent=job.external_ai_enabled;dependencyIds=[...(job.dependency_ids||[])];policy=job.dependency_policy;windowMinutes=job.config?.window_minutes||15;metrics=(job.config?.metrics||[]).map(m=>({...m,min:m.min??'',max:m.max??'',tagsText:Object.keys(m.tags||{}).length?JSON.stringify(m.tags):''}));error='';creating=true;}
  function choose(id){const t=templates.find(t=>t.id===id);if(!t){taskType='analysis';return;}taskType=t.task_type;name=t.name;instructions=t.instructions;interval=t.interval_minutes;windowMinutes=taskType==='handover'?480:15;}
  function metric(){metrics=[...metrics,{connection_id:connections[0]?.id||'',bucket_id:connections[0]?.config?.bucket_ids?.[0]||'',measurement:'',field:'',label:'',unit:'',min:'',max:'',max_age_minutes:5,expected_interval_seconds:10,aggregation:'mean',tagsText:''}];}
  async function save(event){event.preventDefault();busy=true;error='';try{const items=metrics.map(({tagsText,...m})=>({...m,min:m.min===''?null:Number(m.min),max:m.max===''?null:Number(m.max),max_age_minutes:Number(m.max_age_minutes),expected_interval_seconds:Number(m.expected_interval_seconds),tags:tagsText?JSON.parse(tagsText):{}}));const config={...draftConfig,...(editingJob?.config||{}),...(items.length?{metrics:items}:{}),...(['validation','handover'].includes(taskType)?{window_minutes:Number(windowMinutes)}:{})};const payload=editingJob?{name,instructions,model,config,external_ai_enabled:consent,...(editingJob.owner_id===user.id?{dependency_ids:dependencyIds}:{})}:{name,instructions,model:model||null,workspace_id:workspaceId,task_type:taskType,config,timezone,next_run_at:new Date(firstRun).toISOString(),interval_minutes:interval?Number(interval):null,dependency_ids:dependencyIds,dependency_policy:policy,external_ai_enabled:consent};await api(editingJob?`/jobs/${editingJob.id}/definition`:'/jobs',{method:editingJob?'PUT':'POST',body:payload});creating=false;notice=workspaceId?'Job submitted. A manager must approve its current revision before execution.':'Job created.';await load();}catch(e){error=e.message;}finally{busy=false;}}
  async function draftJob(){busy=true;error='';try{const result=await api('/job-drafts',{method:'POST',body:{instructions,workspace_id:workspaceId,...(taskType!=='analysis'?{task_type:taskType}:{}),external_ai_consent:true}});const d=result.draft;name=d.name||name;instructions=d.instructions||instructions;if(!editingJob){taskType=d.task_type||taskType;interval=d.interval_minutes??'';}draftConfig={...draftConfig,...d.config};if(d.config?.window_minutes)windowMinutes=d.config.window_minutes;draftQuestions=[...(result.questions||[]),...(result.metric_suggestions||[]).map(m=>`Configure source for ${m.label}: ${m.minimum??'no minimum'} to ${m.maximum??'no maximum'}.`)];}catch(e){error=e.message;}finally{busy=false;}}
  async function action(job,kind,body={}){busy=true;error='';try{await api(`/jobs/${job.id}/${kind}`,{method:'POST',body});notice=kind==='approve'?'Approved. You have 20 seconds to undo activation.':kind==='run'?'Run queued.':'Job updated.';rejecting=null;comment='';await load();if(selected===job.id)await history(job);}catch(e){error=e.message;}finally{busy=false;}}
  async function toggle(job){busy=true;try{await api(`/jobs/${job.id}`,{method:'PATCH',body:{status:job.status==='active'?'paused':'active'}});await load();}catch(e){error=e.message;}finally{busy=false;}}
  async function history(job){selected=job.id;try{runs=await api(`/jobs/${job.id}/runs`);}catch(e){error=e.message;}}
</script>
{#if error}<div class="banner error" role="alert">{error}</div>{/if}{#if notice}<div class="banner success" role="status">{notice}</div>{/if}
<div class="section-heading"><div><h2>Reliable work, on schedule</h2><p class="help">Validation, shift handovers, briefs, and evidence-based comparisons.</p></div><button class="button primary" onclick={create} disabled={!canWrite}><Plus size={16}/>Schedule work</button></div>
{#if workspaceId}<div class="info-strip"><ShieldCheck size={20}/><p>Workspace automations require a manager’s approval. Dependencies are checked against structured validation outcomes before execution.</p></div>{/if}
<div class="stack">{#each jobs as job}<article class="card job-card"><div class="row-card"><span class="feature-icon"><CalendarClock size={23}/></span><div class="grow"><h3>{job.name}</h3><p class="muted">{job.interval_minutes?`Every ${job.interval_minutes} minutes`:'One-time'} · Next {fmt(job.next_run_at)}</p><small class="muted">{job.task_type?.replaceAll('_',' ')} · {job.timezone||'UTC'} · Revision {job.revision||1}</small></div><span class="tag" class:green={job.status==='active'}>{job.status}</span>{#if job.workspace_id}<span class="tag" class:danger={job.approval_status==='rejected'}>{job.approval_status||'Pending review'}</span>{/if}<div class="row-actions"><button class="button" onclick={()=>history(job)}><Activity size={15}/>Runs</button>{#if job.can_approve&&job.approval_status==='pending'}<button class="button primary" onclick={()=>action(job,'approve',{comment:''})} disabled={busy}><Check size={15}/>Approve</button><button class="button" onclick={()=>{rejecting=job;comment='';}} disabled={busy}>Request changes</button>{/if}{#if job.can_approve&&job.activation_not_before&&new Date(job.activation_not_before).getTime()>now}<button class="button" onclick={()=>action(job,'undo-approval')} disabled={busy}><Undo2 size={15}/>Undo · {Math.ceil((new Date(job.activation_not_before).getTime()-now)/1000)}s</button>{/if}{#if job.owner_id===user.id||job.can_approve}<button class="button" onclick={()=>edit(job)} disabled={busy}>Revise</button>{#if job.status!=='completed'&&(!job.workspace_id||job.approval_status==='approved')}<button class="button" onclick={()=>toggle(job)} disabled={busy}>{#if job.status==='active'}<Pause size={15}/>Pause{:else}<Play size={15}/>Activate{/if}</button><button class="button" onclick={()=>action(job,'run')} disabled={busy}><Play size={15}/>Run now</button>{/if}{#if job.workspace_id&&job.approval_status==='rejected'}<button class="button" onclick={()=>action(job,'submit')} disabled={busy}>Resubmit for review</button>{/if}{/if}</div></div><details><summary>Instructions, sources, and dependencies</summary><p class="pre-wrap">{job.instructions}</p><p class="help">Dependencies: {(job.dependency_ids||[]).map(id=>jobs.find(j=>j.id===id)?.name||id).join(', ')||'None'} · Policy: {job.dependency_policy||'pass_warn'}</p><pre>{JSON.stringify(job.config||{},null,2)}</pre></details>{#if selected===job.id}<div class="runs-panel"><div class="section-heading"><h3>Execution history</h3><button class="text-button" onclick={()=>history(job)}><RefreshCw size={14}/>Refresh</button></div>{#each runs as run}<article class="run-entry"><div><span class="tag" class:danger={run.status==='failed'}>{run.status}</span><span class="muted">{fmt(run.scheduled_for||run.created_at)}</span></div>{#if run.error}<p class="form-error">{run.error}</p>{/if}{#if run.result||run.result_data}<details><summary>Result and evidence</summary><pre>{JSON.stringify(run.result_data||run.result,null,2)}</pre></details>{/if}</article>{:else}<p class="muted">No runs yet. The scheduler records each execution here.</p>{/each}</div>{/if}</article>{:else}<div class="empty card"><CalendarClock size={30}/><h2>Make useful work repeatable.</h2><p>Start with a template and connect the signals or documents it should review.</p><button class="button primary" onclick={create} disabled={!canWrite}>Create your first schedule</button></div>{/each}</div>
{#if creating}<Modal title={editingJob?'Revise scheduled work':'Schedule work'} description={workspaceId?'Create a team-owned job for manager review.':'Create a personal briefing, analysis, or validation job.'} close={()=>creating=false} {busy}><form onsubmit={save}><label>Start from a template<select disabled={!!editingJob} value={taskType} onchange={e=>choose(e.currentTarget.value)}><option value="analysis">Custom analysis</option>{#each templates as template}<option value={template.id}>{template.name}</option>{/each}</select></label><label>Name<input bind:value={name} required/></label><label>Instructions<textarea bind:value={instructions} rows="5" required></textarea></label><label class="check-row"><input type="checkbox" bind:checked={consent}/><span>Allow the configured AI to draft and execute this job using authorized context.</span></label><button type="button" class="button" onclick={draftJob} disabled={busy||!consent||!instructions.trim()||!allowed}>Draft configuration with AI</button>{#if draftQuestions.length}<div class="checkin-prompts"><strong>Review before creating</strong>{#each draftQuestions as question}<p>{question}</p>{/each}</div>{/if}<div class="form-grid"><label>First run · your browser time<input type="datetime-local" bind:value={firstRun} required disabled={!!editingJob}/></label><label>Repeat every minutes<input type="number" min="15" max="20160" bind:value={interval} disabled={!!editingJob}/><small class="help">Leave empty to run once.</small></label><label>Reporting timezone<input bind:value={timezone} required disabled={!!editingJob}/></label><label>Model<select bind:value={model}><option value="">Installation default</option>{#each options as option}<option value={option}>{option}</option>{/each}</select></label></div>
{#if ['validation','handover','production_comparison'].includes(taskType)}<fieldset><legend>Measured signals</legend><p class="help">Statistics are calculated from source data. Missing data is reported as unavailable.</p>{#if taskType!=='production_comparison'}<label>Analysis window (minutes)<input type="number" min="1" max="43200" bind:value={windowMinutes}/></label>{/if}{#each metrics as metric,i}<div class="metric-editor"><div class="section-heading"><h3>Signal {i+1}</h3><button type="button" class="icon-button" aria-label="Remove signal" onclick={()=>metrics=metrics.filter((_,n)=>n!==i)}><Trash2 size={15}/></button></div><label>Influx connection<select bind:value={metric.connection_id} required><option value="">Choose connection</option>{#each connections as c}<option value={c.id}>{c.name}</option>{/each}</select></label><div class="form-grid"><label>Bucket ID<input bind:value={metric.bucket_id} required/></label><label>Measurement<input bind:value={metric.measurement} required/></label><label>Field<input bind:value={metric.field} required/></label><label>Display label<input bind:value={metric.label} required/></label><label>Unit<input bind:value={metric.unit} placeholder="°C, t, %, m³/h" required/></label><label>Aggregation<select bind:value={metric.aggregation}><option value="mean">Mean reading</option><option value="sum">Sum increments</option><option value="counter">Cumulative counter</option></select></label><label>Minimum<input type="number" step="any" bind:value={metric.min}/></label><label>Maximum<input type="number" step="any" bind:value={metric.max}/></label><label>Maximum age (minutes)<input type="number" min="1" bind:value={metric.max_age_minutes}/></label><label>Expected sample interval (seconds)<input type="number" min="1" bind:value={metric.expected_interval_seconds}/></label></div><label>Series tags (JSON)<input bind:value={metric.tagsText} placeholder={'{"furnace":"BF1"}'}/></label></div>{/each}<button type="button" class="button" onclick={metric} disabled={!connections.length}><Plus size={15}/>Add measured signal</button>{#if !connections.length}<p class="help">Add an InfluxDB connection first. A deterministic operational report requires at least one measured signal.</p>{/if}</fieldset>{/if}
{#if draftConfig.alert_rule}<details class="native-artifacts" open><summary>Proposed alert rule · review required</summary><pre>{JSON.stringify(draftConfig.alert_rule,null,2)}</pre><button type="button" class="text-button" onclick={()=>{const {alert_rule,...rest}=draftConfig;draftConfig=rest;}}>Remove proposed rule</button></details>{/if}<fieldset><legend>Run dependencies</legend>{#each jobs as job}<label class="check-row"><input type="checkbox" value={job.id} bind:group={dependencyIds} disabled={editingJob&&editingJob.owner_id!==user.id}/><span>{job.name}</span></label>{:else}<p class="help">No other jobs in this space yet.</p>{/each}<label>Required result<select bind:value={policy} disabled={!!editingJob}><option value="pass">Pass only</option><option value="pass_warn">Pass or warning</option><option value="any">Any completed outcome</option></select></label></fieldset>{#if !allowed}<p class="help">External AI is disabled here. Enable it before running model-based tasks.</p>{/if}{#if error}<p class="form-error" role="alert">{error}</p>{/if}<div class="form-actions"><button type="button" class="button" onclick={()=>creating=false} disabled={busy}>Cancel</button><button class="button primary" disabled={busy||(!consent&&['analysis','morning_brief'].includes(taskType))||(['validation','handover','production_comparison'].includes(taskType)&&!metrics.length)}>{busy?'Saving…':workspaceId?'Submit for approval':'Create schedule'}</button></div></form></Modal>{/if}
{#if rejecting}<Modal title="Request changes" close={()=>rejecting=null} {busy}><form onsubmit={e=>{e.preventDefault();action(rejecting,'reject',{comment});}}><label>What should change?<textarea bind:value={comment} rows="4" required></textarea></label><div class="form-actions"><button type="button" class="button" onclick={()=>rejecting=null}>Cancel</button><button class="button primary" disabled={busy||!comment.trim()}>Send for revision</button></div></form></Modal>{/if}
